// Generated by `vx man --usage` from each command's page, the usage
// fence in its SYNOPSIS (D86); `vx man --check` keeps it in step.
// Don't edit it: edit the page.

enum Usage {
  static let ls = ["usage: ls [-dlmnpqrstuFQT] [file ...]"]
  static let cat = ["usage: cat [file ...]"]
  static let mkdir = ["usage: mkdir [-p] [-m mode] dir..."]
  static let rm = ["usage: rm [-fr] file ..."]
  static let mv = ["usage: mv fromfile tofile", "       mv fromfile ... todir"]
  static let cp = ["usage: cp [-gux] fromfile tofile", "       cp [-x] fromfile ... todir"]
  static let touch = ["usage: touch [-c] [-t time] files"]
  static let man = ["usage: man [-tw] [section ...] title [node]"]
  static let lookman = ["usage: lookman key ..."]
  static let sig = ["usage: sig name ..."]
  static let ps = ["usage: ps [-anpr]"]
  static let kill = ["usage: kill name ..."]
  static let sleep = ["usage: sleep time"]
}
